const tokens = $('02a_busca_tokens').all().map(i => i.json);
const painelTokenRow = tokens.find(t => t.service === 'painel_token');
const tokenEsperado = painelTokenRow ? painelTokenRow.signing_secret : null;
const tokenRecebido = $('01_webhook_get').item.json.query.token || '';

return [{
  json: {
    token_valido: !!tokenEsperado && tokenRecebido === tokenEsperado
  }
}];

const key = $('02a_busca_tokens').all().find(t => t.json.service === 'n8n_api_key').json.signing_secret;
const errosLog = $('04_busca_log_erros').all().map(i => i.json).filter(e => !(e.workflow || '').startsWith('ZZ_TEST_'));
const nomesDistintos = [...new Set(errosLog.map(e => e.workflow).filter(Boolean))];

let workflowsList = [];
try {
  const resp = await this.helpers.httpRequest({
    method: 'GET',
    url: 'https://raregoat-n8n.cloudfy.live/api/v1/workflows',
    qs: { limit: 250 },
    headers: { 'X-N8N-API-KEY': key, 'Accept': 'application/json' },
    json: true,
  });
  workflowsList = resp.data || resp || [];
} catch (e) {
  // listagem falhou -> nenhum nome sera resolvido, nenhum erro sera considerado resolvido (default seguro)
}

const sucessosPorWorkflow = {};
for (const nome of nomesDistintos) {
  const wf = workflowsList.find(w => w.name === nome);
  if (!wf) continue; // nome nao encontrado no n8n -> nao verificavel, mantem o erro visivel
  try {
    const execResp = await this.helpers.httpRequest({
      method: 'GET',
      url: 'https://raregoat-n8n.cloudfy.live/api/v1/executions',
      qs: { workflowId: wf.id, status: 'success', limit: 1 },
      headers: { 'X-N8N-API-KEY': key, 'Accept': 'application/json' },
      json: true,
    });
    const execs = execResp.data || execResp || [];
    if (execs.length > 0) {
      sucessosPorWorkflow[nome] = execs[0].stoppedAt || execs[0].startedAt || null;
    }
  } catch (e) {
    // consulta de execucoes falhou para este workflow -> nao verificavel, mantem o erro visivel
  }
}

return [{ json: { sucessos_por_workflow: sucessosPorWorkflow } }];

// Coleta bruta de cada fonte (referência explícita, nunca $json cru - dados vêm de branches paralelas)
const leads = $('03_busca_base_funil').all().map(i => i.json);
// exclui artefatos de teste (workflow_origem/coluna 'workflow' iniciando com ZZ_TEST_) da contagem e do card
const sucessosPorWorkflow = $('09_verifica_sucessos_recentes').first().json.sucessos_por_workflow || {};
const errosLog = $('04_busca_log_erros').all().map(i => i.json)
  .filter(e => !(e.workflow || '').startsWith('ZZ_TEST_'))
  .filter(e => {
    // erro cujo workflow ja teve execucao com sucesso APOS o timestamp do erro = historico/resolvido, nao exibe
    const ultimoSucesso = sucessosPorWorkflow[e.workflow];
    if (!ultimoSucesso) return true;
    const tErro = new Date(e.timestamp);
    const tSucesso = new Date(ultimoSucesso);
    if (isNaN(tErro) || isNaN(tSucesso)) return true;
    return !(tSucesso > tErro);
  });
const tokens = $('02a_busca_tokens').all().map(i => i.json);
const criticos = $('06a_workflows_criticos').all().map(i => i.json);
const execucoes = $('06_busca_execucoes_n8n').all().map(i => i.json);
const logAceites = $('05_busca_log_aceites').all().map(i => i.json);

const agora = new Date();

// ---------- Seção 2: Saúde da Base ----------
// ---------- Fila do lote de leads (aba leads_importados) ----------
const leadsImportados = $('11_busca_leads_importados').all().map(i => i.json).filter(r => r && (r.status || r.email));
const hojeBR = new Date(agora.toLocaleString('en-US', { timeZone: 'America/Sao_Paulo' }));
hojeBR.setHours(0, 0, 0, 0);
const parseBR = s => { const m = String(s || '').trim().match(/^(\d{2})\/(\d{2})\/(\d{4})/); return m ? new Date(+m[3], +m[2] - 1, +m[1]) : null; };
const vencida = r => { const d = parseBR(r.agendado_para); return !d || d <= hojeBR; };
const filaNovosHoje = leadsImportados.filter(r => r.status === 'agendado' && vencida(r)).length;
const filaReenviosHoje = leadsImportados.filter(r => r.status === 'reenvio_email' && vencida(r)).length;
const filaNovo = leadsImportados.filter(r => r.status === 'novo').length;
const filaFuturo = leadsImportados.filter(r => ['agendado', 'reenvio_email'].includes(r.status) && !vencida(r)).length;
const revisaoManualEmail = leadsImportados.filter(r => r.status === 'revisao_manual_email').length;
const filaLeads = { hoje_total: filaNovosHoje + filaReenviosHoje + filaNovo, hoje_novos: filaNovosHoje + filaNovo, hoje_reenvios: filaReenviosHoje, agendados_futuro: filaFuturo, revisao_manual_email: revisaoManualEmail, total_linhas: leadsImportados.length };

const totalLeads = leads.length;
const cabecalhoIntegro = totalLeads > 0 && Object.prototype.hasOwnProperty.call(leads[0], 'lead_id');
const ultimoLead = totalLeads > 0 ? leads[totalLeads - 1] : null;
const ultimoLeadTimestamp = ultimoLead ? (ultimoLead.data_primeiro_contato || null) : null;

// ---------- Token RD Station (usado na Seção 1, card 6, e na Seção 5) ----------
const tokenRD = tokens.find(t => t.service === 'rdstation') || null;
const rdExpiraEm = (tokenRD && tokenRD.expires_at) ? new Date(tokenRD.expires_at) : null;
const rdDiasParaExpirar = (rdExpiraEm && !isNaN(rdExpiraEm)) ? (rdExpiraEm - agora) / (1000 * 60 * 60 * 24) : null;

// ---------- Seção 1: Status dos Workflows Críticos (agendados) + Seção 1b: Workflows Reativos (informativo) ----------
const statusWorkflowsRaw = criticos.map((c, idx) => {
  const resp = execucoes[idx] || {};
  const lista = resp.data || [];
  const ultima = lista[0] || null;

  // Workflows reativos (só rodam por ação externa, ex.: clique do cliente) não têm
  // "não executou em Xh" como alerta - só reportam a última execução, informativamente.
  if (c.tipo === 'reativo') {
    if (!ultima) {
      return { nome: c.nome, tipo: 'reativo', ultima_execucao: null, ultimo_status: null, motivo: 'nunca executou' };
    }
    const inicio = new Date(ultima.startedAt);
    const horasDesde = (agora - inicio) / (1000 * 60 * 60);
    const falhou = ultima.status === 'error';
    return {
      nome: c.nome,
      tipo: 'reativo',
      ultima_execucao: ultima.startedAt,
      ultimo_status: ultima.status,
      motivo: falhou ? 'última execução falhou' : `última execução há ${horasDesde.toFixed(1)}h`
    };
  }

  let status, horasDesde, motivo;

  if (!ultima) {
    status = 'problema';
    horasDesde = null;
    motivo = 'nunca executou';
  } else {
    const inicio = new Date(ultima.startedAt);
    horasDesde = (agora - inicio) / (1000 * 60 * 60);
    const falhou = ultima.status === 'error';
    const excedeuJanela = horasDesde > c.janela_horas;

    if (falhou || excedeuJanela) {
      // janela de 25h ou menos = severidade vermelha; janela de 48h = severidade amarela
      status = c.janela_horas <= 25 ? 'problema' : 'atencao';
      motivo = falhou ? 'última execução falhou' : `não executou nas últimas ${c.janela_horas}h`;
    } else {
      status = 'ok';
      motivo = `última execução há ${horasDesde.toFixed(1)}h`;
    }
  }

  // Card do RD Station também reflete a validade do token (pode agravar o status, nunca melhorar)
  let detalheToken = '';
  if (c.nome === 'RD Station - Renovar Token') {
    // token RD Station e renovado a cada hora por design (validade de poucas horas, nunca dias) -
    // so e problema real se ja expirou de fato, nao por estar perto de expirar segundo um limiar de dias
    if (rdDiasParaExpirar === null) {
      status = 'problema';
      detalheToken = ' | token RD Station não encontrado na aba tokens';
    } else if (rdDiasParaExpirar < 0) {
      status = 'problema';
      detalheToken = ` | token RD Station expirado há ${Math.abs(rdDiasParaExpirar * 24).toFixed(1)}h`;
    } else {
      detalheToken = ` | token RD Station válido por mais ${(rdDiasParaExpirar * 24).toFixed(1)}h`;
    }
  }

  return {
    nome: c.nome,
    tipo: 'agendado',
    status,
    motivo: motivo + detalheToken
  };
});

const statusWorkflows = statusWorkflowsRaw.filter(w => w.tipo !== 'reativo');
const workflowsReativos = statusWorkflowsRaw.filter(w => w.tipo === 'reativo');

// ---------- Seção 1b: Aceite Digital (card informativo, workflow reativo) ----------
const confirmacoes24h = logAceites.filter(l => {
  const t = new Date(l.timestamp);
  return !isNaN(t) && (agora - t) <= 24 * 60 * 60 * 1000;
}).length;
const confirmacoes7d = logAceites.filter(l => {
  const t = new Date(l.timestamp);
  return !isNaN(t) && (agora - t) <= 7 * 24 * 60 * 60 * 1000;
}).length;

const secaoAceiteDigital = {
  workflows: workflowsReativos,
  total_confirmacoes_registradas: logAceites.length,
  confirmacoes_24h: confirmacoes24h,
  confirmacoes_7d: confirmacoes7d
};

// ---------- Seção 3: Funil em Tempo Real ----------
const funilEtapas = ['Novo Lead', 'Proposta Enviada', 'Em Follow-up', 'Ganho', 'Perdido'];
const funilContagem = funilEtapas.map(etapa => ({
  etapa,
  contagem: leads.filter(l => l.status_funil === etapa).length
}));

const ultimos5Leads = leads.slice(-5).reverse().map(l => ({
  nome: l.nome_contato || l.razao_social || '(sem nome)',
  empresa: l.razao_social || '',
  status: l.status_funil || '',
  ultimo_toque: l.ultimo_toque_data || l.data_primeiro_contato || ''
}));

const leadCapturadoHoje = leads.some(l => {
  if (!l.data_primeiro_contato) return false;
  const d = new Date(l.data_primeiro_contato);
  return !isNaN(d) && d.toDateString() === agora.toDateString();
});

// ---------- Seção 4: Log de Erros Recentes ----------
const ultimosErros = errosLog.slice(-10).reverse().map(e => ({
  timestamp: e.timestamp || '',
  workflow: e.workflow || '',
  mensagem: e.mensagem_erro || '',
  link: e.link_execucao || ''
}));

const erros24h = errosLog.filter(e => {
  const t = new Date(e.timestamp);
  return !isNaN(t) && (agora - t) <= 24 * 60 * 60 * 1000;
});

// ---------- Seção 5: Alertas Ativos (5 regras, ordenadas por severidade) ----------
const alertas = [];

// Regra 1 (🔴): token RD Station ja expirou de fato (renova a cada hora por design, entao
// so alerta quando realmente passou do expires_at - nao por estar perto de expirar em dias)
if (rdDiasParaExpirar !== null && rdDiasParaExpirar < 0) {
  alertas.push({ severidade: 'vermelho', texto: `Token RD Station expirado há ${Math.abs(rdDiasParaExpirar * 24).toFixed(1)}h` });
}

// Regra 2 (🔴): workflow de janela 25h não executou (ou falhou, ou nunca rodou)
statusWorkflows.forEach(w => {
  const c = criticos.find(x => x.nome === w.nome);
  if (c && c.janela_horas <= 25 && w.status === 'problema' && w.nome !== 'RD Station - Renovar Token') {
    alertas.push({ severidade: 'vermelho', texto: `Workflow ${w.nome}: ${w.motivo} (janela de ${c.janela_horas}h)` });
  }
});

// Regra 3 (🔴): cabeçalho da base corrompido
if (!cabecalhoIntegro) {
  alertas.push({ severidade: 'vermelho', texto: 'Cabeçalho da base_funil_completo corrompido (coluna A não é lead_id) — possível bug de aba trocada' });
}

// Regra 4 (🟡): workflow de janela 48h não executou
statusWorkflows.forEach(w => {
  const c = criticos.find(x => x.nome === w.nome);
  if (c && c.janela_horas > 25 && w.status !== 'ok') {
    alertas.push({ severidade: 'amarelo', texto: `Workflow ${w.nome}: ${w.motivo} (janela de 48h)` });
  }
});

// Regra 7 (🟡): leads com e-mail de boas-vindas em revisão manual (3 tentativas falharam)
if (revisaoManualEmail > 0) {
  alertas.push({ severidade: 'amarelo', texto: `${revisaoManualEmail} lead(s) em revisao_manual_email na aba leads_importados (e-mail de boas-vindas falhou 3x)` });
}

// Regra 5 (🟡): nenhum lead capturado hoje
if (!leadCapturadoHoje) {
  alertas.push({ severidade: 'amarelo', texto: 'Nenhum lead capturado hoje' });
}

// Regra 6 (🔴): workflow reativo com última execução em erro (nunca por "não rodou")
workflowsReativos.forEach(w => {
  if (w.ultimo_status === 'error') {
    alertas.push({ severidade: 'vermelho', texto: `Workflow ${w.nome}: última execução falhou` });
  }
});

// ---------- Propostas com falha (Monitor_Propostas_Erros, aba propostas_pendentes_reenvio) ----------
const propostasReenvio = $('12_busca_propostas_reenvio').all().map(i => i.json).filter(r => r && r.execution_id);
const contaStatusProposta = s => propostasReenvio.filter(r => r.status === s).length;
const secaoPropostasReenvio = {
  pendentes: contaStatusProposta('pendente'),
  revisao_manual: contaStatusProposta('revisao_manual'),
  reenviadas_7d: propostasReenvio.filter(r => {
    const t = new Date(r.ultima_tentativa_em);
    return r.status === 'reenviado' && !isNaN(t) && (agora - t) <= 7 * 24 * 60 * 60 * 1000;
  }).length,
  lista: propostasReenvio
    .filter(r => r.status === 'pendente' || r.status === 'revisao_manual')
    .slice(-10).reverse()
    .map(r => ({ razao_social: r.razao_social, causa: r.causa, status: r.status, erro_em: r.erro_em,
                 tentativas: r.tentativas, detalhe: r.resultado_ultima_tentativa || r.observacao, execution_id: r.execution_id }))
};
if (secaoPropostasReenvio.revisao_manual > 0) {
  alertas.push({ severidade: 'vermelho', texto: `${secaoPropostasReenvio.revisao_manual} proposta(s) com falha em revisão manual (aba propostas_pendentes_reenvio)` });
}
if (secaoPropostasReenvio.pendentes > 0) {
  alertas.push({ severidade: 'amarelo', texto: `${secaoPropostasReenvio.pendentes} proposta(s) com falha aguardando o reenvio automático das 21h` });
}

// ordena: vermelho antes de amarelo
alertas.sort((a, b) => (a.severidade === b.severidade ? 0 : a.severidade === 'vermelho' ? -1 : 1));


// ---------- Secao 6: Historico de Erros (30 dias) ----------
function chaveDia(d) {
  return d.toISOString().slice(0, 10); // YYYY-MM-DD
}
const historicoErros30dMap = {};
for (let i = 29; i >= 0; i--) {
  const dia = new Date(agora);
  dia.setDate(dia.getDate() - i);
  historicoErros30dMap[chaveDia(dia)] = 0;
}
errosLog.forEach(e => {
  const t = new Date(e.timestamp);
  if (isNaN(t)) return;
  const chave = chaveDia(t);
  if (chave in historicoErros30dMap) {
    historicoErros30dMap[chave] += 1;
  }
});
const historicoErros30d = Object.entries(historicoErros30dMap).map(([data, contagem]) => ({ data, contagem }));
const somaUltimos7 = historicoErros30d.slice(-7).reduce((s, x) => s + x.contagem, 0);
const somaAnteriores7 = historicoErros30d.slice(-14, -7).reduce((s, x) => s + x.contagem, 0);
let tendencia30d;
if (somaUltimos7 > somaAnteriores7) tendencia30d = 'subindo';
else if (somaUltimos7 < somaAnteriores7) tendencia30d = 'caindo';
else tendencia30d = 'estavel';

return [{
  json: {
    gerado_em: agora.toISOString(),
    secao6_historico_erros_30d: { dias: historicoErros30d, total_ultimos_7d: somaUltimos7, total_7d_anteriores: somaAnteriores7, tendencia: tendencia30d },
    secao1_status_workflows: statusWorkflows,
    secao1b_aceite_digital: secaoAceiteDigital,
    secao2_saude_base: {
      total_leads: totalLeads,
      cabecalho_integro: cabecalhoIntegro,
      ultimo_lead_timestamp: ultimoLeadTimestamp,
      fila_leads: filaLeads
    },
    secao3_funil: {
      etapas: funilContagem,
      ultimos_5_leads: ultimos5Leads
    },
    secao4_log_erros: {
      total_erros_24h: erros24h.length,
      banner_verde: erros24h.length === 0,
      ultimos_erros: ultimosErros
    },
    secao5_alertas: alertas,
    secao7_propostas_reenvio: secaoPropostasReenvio
  }
}];

const d = $('07_consolida_dados').item.json;

const CORES = {
  indigo: '#3A34D6',
  petroleo: '#12786B',
  ambar: '#D9822B',
  vermelho: '#DC2626',
  warmWhite: '#F7F5F1',
  grafite: '#1B1E27'
};

const SHEET_URL_BASE = 'https://docs.google.com/spreadsheets/d/1hN8tekfac-2MQI4YoR7KuVRdd2YmnlGJM62drLdHtfs/edit#gid=810524007';

function escapeHtml(str) {
  return String(str == null ? '' : str)
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;');
}

function formatDataHora(iso) {
  if (!iso) return '—';
  const dt = new Date(iso);
  if (isNaN(dt)) return String(iso);
  return dt.toLocaleString('pt-BR', { dateStyle: 'short', timeStyle: 'short' });
}

function iconeStatus(status) {
  if (status === 'ok') return '🟢';
  if (status === 'atencao') return '🟡';
  return '🔴';
}

// ---------- Seção 1: Status dos Workflows Críticos ----------
function renderSecao1(statusWorkflows) {
  const linhas = statusWorkflows.map(w => `
    <tr>
      <td>${iconeStatus(w.status)}</td>
      <td><strong>${escapeHtml(w.nome)}</strong></td>
      <td>${escapeHtml(w.motivo)}</td>
    </tr>`).join('');

  return `
  <section class="card">
    <h2>Status dos Workflows Críticos</h2>
    <p class="subtitulo">Algum workflow parou?</p>
    <table>
      <thead><tr><th></th><th>Workflow</th><th>Situação</th></tr></thead>
      <tbody>${linhas}</tbody>
    </table>
  </section>`;
}

// ---------- Seção 1b: Aceite Digital (informativo - workflow reativo, nunca alerta "não rodou") ----------
function renderSecaoAceiteDigital(aceite) {
  if (!aceite || !aceite.workflows || aceite.workflows.length === 0) return '';

  const linhas = aceite.workflows.map(w => `
    <tr>
      <td>${w.ultimo_status === 'error' ? '🔴' : '⚪'}</td>
      <td><strong>${escapeHtml(w.nome)}</strong></td>
      <td>${escapeHtml(w.motivo)}</td>
    </tr>`).join('');

  return `
  <section class="card">
    <h2>Workflows Reativos (Aceite Digital, Captura, PDVet, Site e Observabilidade)</h2>
    <p class="subtitulo">Só rodam por evento externo (clique do cliente, formulário, mensagem no WhatsApp, erro em outro workflow). Não alertamos por "não rodou" — só quando a última execução falhou.</p>
    <table>
      <thead><tr><th></th><th>Workflow</th><th>Situação</th></tr></thead>
      <tbody>${linhas}</tbody>
    </table>
    <div class="indicadores-linha" style="margin-top:16px;">
      <div class="indicador">
        <span class="indicador-icone">✅</span>
        <span class="indicador-valor">${aceite.confirmacoes_24h}</span>
        <span class="indicador-label">confirmações nas últimas 24h</span>
      </div>
      <div class="indicador">
        <span class="indicador-icone">✅</span>
        <span class="indicador-valor">${aceite.confirmacoes_7d}</span>
        <span class="indicador-label">confirmações nos últimos 7 dias</span>
      </div>
      <div class="indicador">
        <span class="indicador-icone">📋</span>
        <span class="indicador-valor">${aceite.total_confirmacoes_registradas}</span>
        <span class="indicador-label">total registrado no log</span>
      </div>
    </div>
  </section>`;
}

// ---------- Seção 2: Saúde da Base ----------
function renderSecao2(saude) {
  return `
  <section class="card">
    <h2>Saúde da Base</h2>
    <p class="subtitulo">Os dados estão íntegros?</p>
    <div class="indicadores-linha">
      <div class="indicador">
        <span class="indicador-icone">${saude.total_leads > 0 ? '🟢' : '🔴'}</span>
        <span class="indicador-valor">${saude.total_leads}</span>
        <span class="indicador-label">leads na base</span>
      </div>
      <div class="indicador">
        <span class="indicador-icone">${saude.cabecalho_integro ? '🟢' : '🔴'}</span>
        <span class="indicador-valor">${saude.cabecalho_integro ? 'OK' : 'Corrompido'}</span>
        <span class="indicador-label">cabeçalho (coluna A = lead_id)</span>
      </div>
      <div class="indicador">
        <span class="indicador-icone">🕒</span>
        <span class="indicador-valor">${formatDataHora(saude.ultimo_lead_timestamp)}</span>
        <span class="indicador-label">último lead capturado</span>
      </div>
    </div>
    <p class="subtitulo" style="margin-top:16px">Fila do lote de leads (aba leads_importados)</p>
    <div class="indicadores-linha">
      <div class="indicador">
        <span class="indicador-icone">${(saude.fila_leads && saude.fila_leads.hoje_total > 0) ? '🟡' : '🟢'}</span>
        <span class="indicador-valor">${saude.fila_leads ? saude.fila_leads.hoje_total : 0}</span>
        <span class="indicador-label">aguardando hoje (${saude.fila_leads ? saude.fila_leads.hoje_novos : 0} novos + ${saude.fila_leads ? saude.fila_leads.hoje_reenvios : 0} reenvios)</span>
      </div>
      <div class="indicador">
        <span class="indicador-icone">📅</span>
        <span class="indicador-valor">${saude.fila_leads ? saude.fila_leads.agendados_futuro : 0}</span>
        <span class="indicador-label">agendados para os próximos dias</span>
      </div>
      <div class="indicador">
        <span class="indicador-icone">${(saude.fila_leads && saude.fila_leads.revisao_manual_email > 0) ? '🔴' : '🟢'}</span>
        <span class="indicador-valor">${saude.fila_leads ? saude.fila_leads.revisao_manual_email : 0}</span>
