}

// ---------- Seção 3: Funil em Tempo Real ----------
function renderSecao3(funil) {
  const maxContagem = Math.max(1, ...funil.etapas.map(e => e.contagem));
  const miniFunil = funil.etapas.map(e => `
    <div class="funil-etapa">
      <div class="funil-barra" style="height:${8 + (e.contagem / maxContagem) * 60}px;"></div>
      <div class="funil-contagem">${e.contagem}</div>
      <div class="funil-label">${escapeHtml(e.etapa)}</div>
    </div>`).join('');

  const linhasLeads = funil.ultimos_5_leads.map(l => `
    <tr class="linha-clicavel" onclick="window.open('${SHEET_URL_BASE}', '_blank')">
      <td>${escapeHtml(l.nome)}</td>
      <td>${escapeHtml(l.empresa)}</td>
      <td>${escapeHtml(l.status)}</td>
      <td>${formatDataHora(l.ultimo_toque)}</td>
    </tr>`).join('') || '<tr><td colspan="4">Nenhum lead na base ainda.</td></tr>';

  return `
  <section class="card">
    <h2>Funil em Tempo Real</h2>
    <p class="subtitulo">Como está o pipeline hoje?</p>
    <div class="mini-funil">${miniFunil}</div>
    <table>
      <thead><tr><th>Nome</th><th>Empresa</th><th>Status</th><th>Último toque</th></tr></thead>
      <tbody>${linhasLeads}</tbody>
    </table>
  </section>`;
}

// ---------- Seção 4: Log de Erros Recentes ----------
function renderSecao4(log) {
  const banner = log.banner_verde
