      <tbody>${linhas}</tbody>
    </table>
  </section>`;
}

// ---------- Secao 6: Historico de Erros (30 dias) ----------
function renderSecao6(hist) {
  const dias = hist.dias || [];
  const max = Math.max(1, ...dias.map(d => d.contagem));
  const larguraBarra = 18;
  const gap = 4;
  const alturaMax = 90;
  const larguraSvg = dias.length * (larguraBarra + gap);
  const alturaSvg = alturaMax + 30;

  const barras = dias.map((d, i) => {
    const h = Math.round((d.contagem / max) * alturaMax);
    const x = i * (larguraBarra + gap);
    const y = alturaMax - h;
    const cor = d.contagem > 0 ? CORES.vermelho : '#E5E1D8';
    return `<rect x="${x}" y="${y}" width="${larguraBarra}" height="${Math.max(h, 1)}" fill="${cor}" rx="2">` +
           `<title>${d.data}: ${d.contagem} erro(s)</title></rect>`;
  }).join('');

  const primeiraData = dias.length ? dias[0].data : '';
  const ultimaData = dias.length ? dias[dias.length - 1].data : '';

  const tendenciaLabel = { subindo: '📈 subindo', caindo: '📉 caindo', estavel: '➡️ estável' }[hist.tendencia] || hist.tendencia;
  const tendenciaCor = hist.tendencia === 'subindo' ? CORES.vermelho : (hist.tendencia === 'caindo' ? CORES.petroleo : '#5B5F6B');

  return `
  <section class="card">
    <h2>Histórico de Erros (30 dias)</h2>
    <p class="subtitulo">Contagem de erros por dia — ${escapeHtml(primeiraData)} a ${escapeHtml(ultimaData)}</p>
    <svg width="${larguraSvg}" height="${alturaSvg}" viewBox="0 0 ${larguraSvg} ${alturaSvg}" style="max-width:100%; height:auto;">
      ${barras}
    </svg>
    <p style="font-size:13px; margin-top:8px;">
      Últimos 7 dias: <strong>${hist.total_ultimos_7d}</strong> erro(s) ·
      7 dias anteriores: <strong>${hist.total_7d_anteriores}</strong> ·
      Tendência: <strong style="color:${tendenciaCor};">${tendenciaLabel}</strong>
    </p>
  </section>`;
}

// ---------- Propostas com falha (Monitor_Propostas_Erros) ----------
function renderSecaoPropostasReenvio(p) {
  if (!p) return '';
  const ROTULO_CAUSA = { cota_resend: 'Cota do Resend', rede: 'Rede', rate_limit: 'Rate limit', schema_cache: 'Schema em cache', cnpj_invalido: 'CNPJ inválido', nao_identificada: 'Não identificada' };
  const urlAba = 'https://docs.google.com/spreadsheets/d/1hN8tekfac-2MQI4YoR7KuVRdd2YmnlGJM62drLdHtfs/edit#gid=714364179';
  const linhas = (p.lista || []).map(r => `
    <tr>
      <td>${formatDataHora(r.erro_em)}</td>
      <td>${escapeHtml(r.razao_social || '—')}</td>
      <td>${escapeHtml(ROTULO_CAUSA[r.causa] || r.causa || '—')}</td>
      <td>${r.status === 'revisao_manual' ? '🔴 revisão manual' : '🟡 reenvio às 21h'}${Number(r.tentativas) > 0 ? ` (${escapeHtml(r.tentativas)} tentativa(s))` : ''}</td>
      <td>${escapeHtml(r.detalhe || '')}</td>
      <td><a href="https://raregoat-n8n.cloudfy.live/workflow/EQ3YEDcPysyaFlZp/executions/${escapeHtml(r.execution_id)}" target="_blank">Ver execução</a></td>
    </tr>`).join('') || '<tr><td colspan="6">Nenhuma proposta com falha pendente.</td></tr>';
  return `
  <section class="card">
    <h2>Propostas com Falha</h2>
    <p class="subtitulo">Alguma proposta deixou de chegar ao cliente?</p>
    <p style="font-size:13px;">
      Aguardando reenvio: <strong>${p.pendentes}</strong> ·
      Revisão manual: <strong style="color:${p.revisao_manual > 0 ? CORES.vermelho : 'inherit'};">${p.revisao_manual}</strong> ·
      Reenviadas nos últimos 7 dias: <strong>${p.reenviadas_7d}</strong> ·
      <a href="${urlAba}" target="_blank">abrir aba de controle</a>
    </p>
    <table>
      <thead><tr><th>Falhou em</th><th>Empresa</th><th>Causa</th><th>Situação</th><th>Detalhe</th><th>Execução</th></tr></thead>
      <tbody>${linhas}</tbody>
    </table>
  </section>`;
}

// ---------- Seção 5: Alertas Ativos ----------
function renderSecao5(alertas) {
  if (!alertas || alertas.length === 0) return '';
  const linhas = alertas.map(a => `
    <li class="alerta alerta-${a.severidade}">
      ${a.severidade === 'vermelho' ? '🔴' : '🟡'} ${escapeHtml(a.texto)}
